===== EnsureOwnerIdentityUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects creating an owner whose derived {@code identityKey} exactly matches an existing owner's.
 *
 * <p>The key — {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the one
 * place duplicate detection now lives, replacing the former separate telephone, email and household
 * checks. Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed; only an
 * exact full-key match is a duplicate.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone}/{@link NormalizeOwnerEmail} (so the key uses
 * canonical values) and after {@link AssignHouseholdId} (so the {@code householdId} component is
 * populated), and before {@link SaveOwner} so a duplicate is a 409 (Conflict) rather than a
 * persisted row.
 */
public class EnsureOwnerIdentityUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = owner.getIdentityKey();
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue;
            }
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner is treated as absent
            }
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== EnsureHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects creating an owner that would silently join an existing household at the same residence.
 * The {@code householdId} is deterministic — computed from {@code (normalizedLastName, postcode)} by
 * {@link AssignHouseholdId} — but a postcode alone can be shared coincidentally by unrelated cities
 * (an unknown-region city accepts any 4-digit postcode), so a shared {@code householdId} on its own
 * does not prove a shared residence. A second owner is treated as a household duplicate only when it
 * shares both the {@code householdId} <em>and</em> the same city as an existing member — same surname,
 * same postcode, same city — and is then rejected with 409 (Conflict) via
 * {@link DuplicateHouseholdException}. Same surname and postcode but a different city are distinct
 * residences and are admitted (their {@code membershipLevel} is then capped against any true household
 * member by {@link CapMembershipLevel}).
 *
 * <p>The request may acknowledge the shared household by setting {@code sharesHousehold} true; that
 * bypasses this block and the owner is created as a declared household member (and, being declared, is
 * not flagged as a possible duplicate by {@link AssignPossibleDuplicate}). Owners with no postcode have
 * no {@code householdId} and so are never household duplicates.
 *
 * <p>This is distinct from {@link EnsureOwnerIdentityUnique}, which rejects an exact identity match
 * (same telephone, email and household) regardless of {@code sharesHousehold}.
 *
 * <p>Runs after {@link AssignHouseholdId} (so the {@code householdId} is populated) and before
 * {@link SaveOwner}, so a duplicate is a 409 rather than a persisted row.
 */
public class EnsureHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // acknowledged: create as a declared household member
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null || householdId.isBlank()) {
            return; // no household to clash with
        }
        String city = normalizeCity(owner.getCity());
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                continue;
            }
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner is treated as absent
            }
            if (householdId.equals(existing.getHouseholdId())
                    && city.equals(normalizeCity(existing.getCity()))) {
                throw new DuplicateHouseholdException(householdId);
            }
        }
    }

    /** Trim and lower-case the city so residence comparison ignores casing and surrounding space. */
    private static String normalizeCity(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }
}
===== AssignHouseholdId =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the new owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256
 * over {@code normalizedLastName + '|' + postcode}. Because the identifier is a pure function of the
 * last name and postcode, every owner with the same last name and postcode derives the same value and
 * so belongs to the same household automatically — there is no linking step and no back-fill.
 *
 * <p>The last name is normalized (trimmed, internal whitespace collapsed, lower-cased) before hashing,
 * so trivially different spellings map to one household. The identifier keys off the postcode alone,
 * not the free-text address, so a household needs a postcode: when the request has no postcode the
 * owner has no household and {@code householdId} is left null.
 *
 * <p>Note the change from earlier behaviour: {@code sharesHousehold} no longer creates the household
 * link (the link is now automatic); it only bypasses the household-duplicate block in
 * {@link EnsureHouseholdUnique}.
 *
 * <p>Runs after {@link BuildOwner} (so the entity, its last name and postcode exist) and before both
 * {@link EnsureHouseholdUnique} and {@link SaveOwner}, mutating the not-yet-persisted owner in place.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // no postcode -> no household
        }
        String lastName = normalize(owner.getLastName());
        owner.setHouseholdId(stableId(lastName, postcode.trim()));
    }

    /** Trim, collapse internal whitespace to a single space and lower-case for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** First 12 hex characters of SHA-256 over the normalized last name and the postcode. */
    private static String stableId(String lastName, String postcode) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 12);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
===== AssignPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a soft (non-hard) duplicate. The new owner is created regardless, but when it is not an exact
 * identity match yet shares an existing owner's last name and postcode while having a different
 * telephone, it is recorded as a possible duplicate of that owner.
 *
 * <p>A <em>declared</em> household member — a request that set {@code sharesHousehold} to join a known
 * household — is never a suspected duplicate: it was accepted deliberately, so this step clears the
 * flag and returns. (Without {@code sharesHousehold}, a second owner sharing the household is instead
 * rejected outright by {@link EnsureHouseholdUnique}, so it never reaches this step.)
 *
 * <p>Otherwise sets {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the matching
 * owner's id (the lowest-id match when several qualify, so the value is deterministic); otherwise
 * {@code possibleDuplicate} is set false and {@code possibleDuplicateOf} left null. Hard duplicates —
 * an exact identity-key match — never reach here: they are rejected earlier by
 * {@link EnsureOwnerIdentityUnique}.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} (so telephones compare in canonical form) and after
 * {@link BuildOwner} (so the entity, its last name and postcode exist), and before {@link SaveOwner}
 * so the flag is persisted with the new row and read back by {@code GET /api/owners/{id}}.
 */
public class AssignPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return; // a declared household member is not a suspected duplicate
        }
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();

        Integer matchId = null;
        if (postcode != null && !postcode.isBlank()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
                    continue;
                }
                if (Boolean.TRUE.equals(existing.getDeleted())) {
                    continue; // a soft-deleted owner is treated as absent
                }
                if (equalsIgnoreCase(lastName, existing.getLastName())
                        && postcode.equals(existing.getPostcode())
                        && !equals(telephone, existing.getTelephone())) {
                    if (matchId == null || existing.getId() < matchId) {
                        matchId = existing.getId();
                    }
                }
            }
        }

        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    private static boolean equals(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

