/** Extract the numeric id from a create response body or its Location header. */
private int extractId(org.springframework.test.web.servlet.ResultActions ra) throws Exception {
    String location = ra.andReturn().getResponse().getHeader("Location");
    if (location != null && location.contains("/")) {
        return Integer.parseInt(location.substring(location.lastIndexOf('/') + 1));
    }
    String body = ra.andReturn().getResponse().getContentAsString();
    return com.fasterxml.jackson.databind.json.JsonMapper.builder().build()
            .readTree(body).get("id").asInt();
}

